css:
.prescription {
	font-family: Helvetica, Arial, sans-serif;
	color: #16233a;
	font-size: 10.5pt;
	line-height: 1.5;
}
.rx-header {
	display: flex;
	justify-content: space-between;
	align-items: baseline;
	border-bottom: 0.5mm solid #1f3b73;
	padding-bottom: 3mm;
	margin-bottom: 4mm;
}
.rx-brand { font-size: 15pt; font-weight: bold; color: #1f3b73; }
.rx-issuer { font-size: 9pt; color: #5a6a85; }
.rx-meta {
	display: flex;
	justify-content: space-between;
	font-size: 9pt;
	color: #5a6a85;
	margin-bottom: 5mm;
}
.field-label { font-size: 7.5pt; text-transform: uppercase; letter-spacing: 0.3mm; color: #5a6a85; }
.patient-table { width: 100%; border-collapse: collapse; margin: 0 0 5mm; }
.prescription .patient-table td { padding: 1.2mm 0 !important; vertical-align: top; }
.patient-table td.field-label { width: 32mm; }
.rx-diagnosis { margin: 1mm 0 5mm; }
.medicine-table { width: 100%; border-collapse: collapse; margin-bottom: 8mm; }
.prescription .medicine-table th {
	font-size: 7.5pt;
	font-weight: normal;
	text-transform: uppercase;
	letter-spacing: 0.3mm;
	color: #5a6a85;
	text-align: left;
	border-bottom: 0.3mm solid #1f3b73;
	padding: 1.5mm 2mm 1.5mm 0 !important;
}
.prescription .medicine-table td {
	border-bottom: 0.3mm solid #d5dae3;
	padding: 2mm 2mm 2mm 0 !important;
	vertical-align: top;
}
.prescription .medicine-table .rx-index { width: 6mm; color: #5a6a85; }
.prescription .medicine-table .rx-number { width: 12mm; text-align: right; }
.rx-medicine { font-weight: bold; }
.rx-instructions { font-size: 9pt; color: #5a6a85; white-space: pre-wrap; }
.rx-signature { margin-top: 10mm; }
.rx-org { font-size: 9pt; color: #5a6a85; }
.rx-footer { margin-top: 8mm; font-size: 8pt; color: #5a6a85; border-top: 0.3mm solid #d5dae3; padding-top: 3mm; }
